import {sampleData,parseCSV,csv,sum,select,daily,forecast,channels} from './engine.js';
let rows=sampleData(),source='Synthetic demo',view='overview';
const $=s=>document.querySelector(s),fmt=n=>new Intl.NumberFormat('en-IN',{maximumFractionDigits:0}).format(n),money=n=>'₹'+fmt(n),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors=['#496c4d','#91ad71','#c1d69c','#dde7c7'];
const labels={overview:['Overview','A clearer view of demand.','Understand what is selling. Decide what comes next.'],channels:['Channel insights','Know where growth comes from.','Compare channel efficiency before your next budget decision.'],forecast:['Demand planner','Plan the next two weeks.','Turn recent sales into a transparent stock scenario.'],data:['Your data','Your data. Your perspective.','A simple CSV is all you need to get started.']};
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function switchView(v){view=v;for(const el of document.querySelectorAll('.view'))el.hidden=el.id!==v;for(const b of document.querySelectorAll('nav button')){b.classList.toggle('active',b.dataset.view===v);b.setAttribute('aria-current',b.dataset.view===v?'page':'false');}$('#crumb').textContent=labels[v][0];$('#page-title').textContent=labels[v][1];$('#page-description').textContent=labels[v][2];$('#filters').hidden=v==='data';}
function populate(){for(const [id,key] of [['channel','channel'],['product','product']]){$('#'+id).innerHTML='<option value="All">All '+(id==='channel'?'channels':'products')+'</option>'+[...new Set(rows.map(r=>r[key]))].sort().map(s=>`<option value="${escape(s)}">${escape(s)}</option>`).join('');}}
function selection(){return select(rows,{channel:$('#channel').value,product:$('#product').value,days:Number($('#period').value)});}
function chart(points,{band=false}={}){
  if(!points.length)return '<div class="empty">Add at least 14 dates of sales data to generate a forecast.</div>';
  const w=650,h=245,left=45,right=15,top=18,bottom=35,max=Math.max(1,...points.map(p=>band?p.high:p.units))*1.12;
  const x=i=>left+i*(w-left-right)/Math.max(1,points.length-1),y=v=>h-bottom-v/max*(h-top-bottom);
  const path=points.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(p.units).toFixed(1)}`).join(' ');
  let inside='';for(let i=0;i<5;i++){const v=max*i/4;inside+=`<line class="grid" x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}"/><text x="${left-9}" y="${y(v)+3}" text-anchor="end">${fmt(v)}</text>`;}
  if(band){const area=points.map((p,i)=>`${x(i)},${y(p.high)}`).concat([...points].reverse().map((p,i)=>`${x(points.length-1-i)},${y(p.low)}`)).join(' ');inside+=`<polygon points="${area}" fill="#e9f0dc"/>`;}
  else inside+=`<path d="${path} L${x(points.length-1)},${h-bottom} L${left},${h-bottom} Z" fill="#eff4e8"/>`;
  inside+=`<path d="${path}" fill="none" stroke="#698b52" stroke-width="2.4" stroke-linejoin="round"/>`;
  const marks=[...new Set([0,Math.floor((points.length-1)/3),Math.floor((points.length-1)*2/3),points.length-1])];
  for(const i of marks){const p=points[i];inside+=`<text x="${x(i)}" y="${h-9}" text-anchor="middle">${p.date.slice(8)} ${new Date(p.date+'T00:00:00Z').toLocaleString('en',{month:'short',timeZone:'UTC'})}</text>`;}
  return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${band?'Projected':'Daily'} units sold, ${points[0].date} to ${points.at(-1).date}. Minimum ${fmt(Math.min(...points.map(p=>p.units)))}, maximum ${fmt(Math.max(...points.map(p=>p.units)))} units."><title>${band?'Demand forecast':'Daily demand'}</title>${inside}</svg>`;
}
function change(current,previous){if(!previous)return current?'No prior baseline':'No change';const rate=(current/previous-1)*100;return (rate>=0?'+':'')+rate.toFixed(1)+'%';}
function render(){const s=selection(),r=s.current,p=s.previous,c=channels(r),f=forecast(s.all,s.end);$('#date-range').textContent=s.start+' — '+s.end;
  const metrics=[['Revenue',money(sum(r,'revenue')),change(sum(r,'revenue'),sum(p,'revenue'))],['Orders',fmt(sum(r,'orders')),change(sum(r,'orders'),sum(p,'orders'))],['Units sold',fmt(sum(r,'units')),change(sum(r,'units'),sum(p,'units'))],['New customers*',fmt(sum(r,'new_customers')),change(sum(r,'new_customers'),sum(p,'new_customers'))]];
  $('#metrics').innerHTML=metrics.map(([label,value,delta])=>`<article class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><small><span>${delta}</span> vs previous ${$('#period').value} days</small></article>`).join('');
  $('#demand-chart').innerHTML=chart(daily(r,s.start,s.end));
  const revenue=sum(r,'revenue');$('#channel-mix').innerHTML=`<div class="mix-total">${money(revenue)}</div><div class="mix-caption">Total revenue in this selection</div><div class="stacked">${c.map((a,i)=>`<div style="width:${revenue?a.revenue/revenue*100:0}%;background:${colors[i%4]}" title="${escape(a.channel)}"></div>`).join('')}</div>${c.length?c.map((a,i)=>`<div class="mix-line"><span><i class="swatch" style="background:${colors[i%4]}"></i>${escape(a.channel)}</span><strong>${revenue?(a.revenue/revenue*100).toFixed(1):0}%</strong></div>`).join(''):'<p>No sales for this selection.</p>'}`;
  const products=[...new Set(r.map(a=>a.product))].map(product=>({product,units:sum(r.filter(a=>a.product===product),'units')})).sort((a,b)=>b.units-a.units);
  $('#products').innerHTML=products.length?products.slice(0,6).map(a=>`<div class="product-row"><b>${escape(a.product)}</b><div class="bar-bg"><div class="bar" style="width:${a.units/Math.max(1,products[0].units)*100}%"></div></div><span>${fmt(a.units)} units</span></div>`).join(''):'<p>No matching products.</p>';
  const efficient=[...c].filter(a=>a.roas!==null).sort((a,b)=>b.roas-a.roas)[0];
  $('#insight-title').textContent=efficient?`${efficient.channel} leads on revenue per rupee.`:'Build a baseline first.';
  $('#insight-body').textContent=efficient?`It returns ₹${efficient.roas.toFixed(2)} in recorded revenue per ₹1 of channel spend. Review margin and capacity before testing a budget increase.`:'Import sales with recorded channel spend to compare revenue efficiency.';
  $('#channel-table').innerHTML=c.map(a=>`<tr><td>${escape(a.channel)}</td><td>${fmt(a.orders)}</td><td>${money(a.revenue)}</td><td>${money(a.spend)}</td><td>${a.roas===null?'N/A':a.roas.toFixed(2)+'×'}</td><td>${fmt(a.customers)}</td><td>${a.cac===null?'N/A':money(a.cac)}</td></tr>`).join('')||'<tr><td colspan="7">No matching sales.</td></tr>';
  $('#forecast-chart').innerHTML=chart(f.points,{band:true});$('#forecast-total').textContent=f.points.length?fmt(f.total)+' units':'Not enough data';
  $('#forecast-status').textContent=f.points.length?`Observed weekly change after cap: ${(f.growth*100).toFixed(1)}%. Forecast starts ${f.points[0].date}.`:'Forecast unavailable: supply at least 14 distinct dates in the latest 28-day window.';stockResult();
}
function stockResult(){const s=selection(),f=forecast(s.all,s.end),raw=$('#stock').value,available=Number(raw);if(!f.points.length){$('#stock-result').textContent='Add more history to use the stock scenario.';return;}if(raw===''||!Number.isInteger(available)||available<0||available>1e9){$('#stock-result').textContent='Enter a whole number from 0 to 1,000,000,000.';return;}const gap=available-f.total;$('#stock-result').textContent=gap>=0?`${fmt(gap)} units above the baseline forecast. The upper planning range needs ${fmt(sum(f.points,'high'))} units.`:`${fmt(-gap)} additional units needed to meet the baseline forecast. Check individual product availability.`;}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportPlan(){const s=selection(),r=s.current,f=forecast(s.all,s.end),c=channels(r);const lines=['NXTGEN DEMAND — ACTION PLAN',`Data source: ${source}`,`Period: ${s.start} to ${s.end}`,`Filters: ${$('#channel').value} / ${$('#product').value}`,'',`Revenue (INR): ${sum(r,'revenue')}`,`Orders: ${sum(r,'orders')}`,`Units: ${sum(r,'units')}`,`New customers (sum of supplied counts, may overlap): ${sum(r,'new_customers')}`,'','CHANNEL COMPARISON',...c.map(a=>`${a.channel}: revenue INR ${a.revenue}; spend INR ${a.spend}; revenue/spend ${a.roas?.toFixed(2)??'N/A'}; cost/new customer INR ${a.cac?.toFixed(2)??'N/A'}`),'', 'NEXT ACTION', $('#insight-title').textContent,$('#insight-body').textContent,'','14-DAY DEMAND SCENARIO',f.points.length?`Baseline ${f.total} units; planning range ${sum(f.points,'low')} to ${sum(f.points,'high')} units.`:'Insufficient history for forecast.',...f.points.map(p=>`${p.date}: ${p.units} units (${p.low} to ${p.high})`),'','METHOD AND LIMITS','Last 7 days repeated by weekday, with weekly growth capped at +/-25% and applied across the horizon. Missing days count as zero. At least 14 observed dates in the latest 28 days required. Planning bands are +/-20%, not confidence intervals.','Revenue/spend is not profit or causal attribution. New customer counts may overlap across channels. Stock scenario is aggregate only. Review margins, returns, stockouts, promotions, and lead times before acting.'];download('nxtgen-action-plan.txt',lines.join('\n'),'text/plain;charset=utf-8');notify('Action plan downloaded.');}
for(const b of document.querySelectorAll('nav button'))b.addEventListener('click',()=>switchView(b.dataset.view));
for(const id of ['period','channel','product'])$('#'+id).addEventListener('change',render);
$('#stock').addEventListener('input',stockResult);$('#export').addEventListener('click',exportPlan);$('#import-open').addEventListener('click',()=>switchView('data'));$('#planner-open').addEventListener('click',()=>switchView('forecast'));
$('#sample-download').addEventListener('click',()=>download('nxtgen-sample.csv',csv(sampleData()),'text/csv;charset=utf-8'));
$('#file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5_000_000)throw Error('File exceeds the 5 MB limit.');const imported=parseCSV(await file.text());rows=imported;source='Imported CSV';populate();render();$('#data-label').textContent='Your data is ready';$('#data-description').textContent=`${fmt(rows.length)} rows. Stored only in this browser session.`;$('#import-status').textContent=`Imported ${fmt(rows.length)} rows successfully. Open Overview to explore your data.`;notify('CSV imported successfully.');}catch(err){$('#import-status').textContent='Import failed: '+err.message;}finally{e.target.value='';}});
$('#reset').addEventListener('click',()=>{rows=sampleData();source='Synthetic demo';populate();render();$('#data-label').textContent='Explore the demo workspace';$('#data-description').textContent='Synthetic retail data. No customer information.';$('#import-status').textContent='Demo data restored.';notify('Demo data restored.');});
populate();render();switchView('overview');
